insert into vocab_cards (word, phonetic, synonym, antonym, meaning_en, meaning_vi, example_sentence, exam_type, cefr_level, category) values
  ('a', '/ə/', 'an', NULL, 'Used before a singular noun to indicate one unspecified thing; the indefinite article.', 'một (mạo từ không xác định)', 'She saw a bird in the garden.', '{IELTS}', 'A1', 'Grammar'),
  ('i', '/aɪ/', '[''myself'', ''me'', ''oneself'', ''self'', ''iodine'']', '[''you'', ''they'', ''we'', ''he'', ''she'']', 'Used by a speaker to refer to himself or herself.', 'tôi', 'I am a student.', '{IELTS}', 'A1', 'Pronouns'),
  ('on', '/ɒn/', 'upon', 'off', 'In contact with and supported by a surface.', 'trên', 'The book is on the table.', '{IELTS}', 'A1', 'Position'),
  ('was', '/wɒz/', NULL, 'were', 'First- and third-person singular past tense of ''be''.', 'đã là, đã (quá khứ số ít)', 'He was late to the meeting.', '{IELTS}', 'A1', 'Grammar'),
  ('be', '/biː/', 'exist', NULL, 'To exist or occur; base form of the auxiliary verb ''be''.', 'thì, là, ở', 'I want to be a doctor someday.', '{IELTS}', 'A1', 'Grammar'),
  ('as', '/æz/', '[''like'', ''since'', ''because'', ''while'', ''when'']', '[''unlike'', ''different from'', ''dissimilar to'', ''contrary to'', ''opposed to'']', 'Used to refer to the function or character of someone or something.', 'như, khi mà, bởi vì', 'He works as a teacher.', '{IELTS}', 'A1', 'Conjunctions'),
  ('have', '/hæv/', 'possess', 'lack', 'To possess, own, or experience; also an auxiliary forming perfect tenses.', 'có, sở hữu', 'I have a meeting at noon.', '{IELTS}', 'A1', 'Grammar'),
  ('at', '/æt/', '[''near'', ''by'', ''beside'', ''close to'', ''next to'']', '[''away from'', ''far from'', ''distant from'', ''removed from'', ''apart from'']', 'Expressing location or time.', 'tại, ở', 'I am at home.', '{IELTS}', 'A1', 'Prepositions'),
  ('he', '/hiː/', '[''him'', ''his'', ''himself'', ''the man'', ''that male'']', '[''she'', ''they'', ''it'', ''we'', ''you'']', 'Used to refer to a male person or animal already mentioned or easily identified.', 'anh ấy, ông ấy', 'He is my brother.', '{IELTS}', 'A1', 'Pronouns'),
  ('not', '/nɒt/', NULL, 'yes', 'Adverb used to form negatives; expressing negation or denial.', 'không', 'I am not going to the party.', '{IELTS}', 'A1', 'Grammar'),
  ('by', '/baɪ/', '[''near'', ''beside'', ''via'', ''through'', ''past'']', '[''far from'', ''away from'', ''distant'', ''remote'', ''isolated'']', 'Indicating the agent or means of an action.', 'bởi, bằng', 'The book was written by him.', '{IELTS}', 'A1', 'Prepositions'),
  ('or', '/ɔːr/', 'otherwise', 'and', 'A conjunction used to link alternatives or choices.', 'hoặc, hay', 'Would you like tea or coffee?', '{IELTS}', 'A1', 'Grammar'),
  ('all', '/ɔːl/', 'every', 'none', 'The whole quantity or number of; every member or part of.', 'tất cả', 'All students must submit their work by Friday.', '{IELTS}', 'A1', 'Grammar'),
  ('so', '/soʊ/', 'therefore', NULL, 'Conjunction indicating result or consequence; to such an extent.', 'vì vậy, quá', 'It was raining, so we took an umbrella.', '{IELTS}', 'A1', 'Grammar'),
  ('can', '/kæn/', 'could', 'cannot', 'Auxiliary verb expressing ability or possibility.', 'có thể', 'She can speak three languages.', '{IELTS}', 'A1', 'Grammar'),
  ('will', '/wɪl/', 'shall', 'won''t', 'Auxiliary verb expressing the future tense or a strong intention.', 'sẽ', 'I will call you tomorrow.', '{IELTS}', 'A1', 'Grammar'),
  ('just', '/dʒʌst/', 'exactly', 'unfairly', 'Exactly; only; a moment ago; fair and right.', 'vừa mới, chỉ, công bằng', 'I just finished my homework.', '{IELTS}', 'A1', 'Grammar'),
  ('like', '/laɪk/', '[''enjoy'', ''love'', ''prefer'', ''fancy'', ''adore'']', '[''dislike'', ''hate'', ''detest'', ''despise'', ''abhor'']', 'To find pleasant or attractive.', 'thích, giống như', 'I like apples.', '{IELTS}', 'A1', 'Verbs'),
