  ('follow', '/ˈfɒloʊ/', '[''pursue'', ''trail'', ''accompany'', ''obey'', ''track'']', '[''lead'', ''guide'', ''direct'', ''precede'', ''head'']', 'go or come after (a person or thing proceeding ahead).', 'đi theo, tuân theo', 'Please follow the instructions on the screen.', '{IELTS}', 'A1', 'Verbs'),
  ('lives', '/laɪvz/', '[''existences'', ''life'', ''living'', ''animation'', ''aliveness'']', '[''inexperience'', ''stay in place'', ''come'', ''malfunction'', ''be born'']', 'plural of life; the conditions of individual human beings.', 'cuộc sống (số nhiều)', 'The doctors saved many lives during the emergency.', '{IELTS}', 'A1', 'Nouns'),
  ('leave', '/liːv/', '[''vacation'', ''depart'', ''exit'', ''vacate'', ''abandon'']', '[''work'', ''stay'', ''remain'', ''arrive'', ''enter'']', 'time when one has permission to be absent from work or duty.', 'kỳ nghỉ phép, rời đi', 'She is currently on maternity leave.', '{IELTS}', 'A2', 'Nouns'),
  ('north', '/nɔːrθ/', '[''union'', ''due north'', ''northward'', ''n'', ''magnetic north'']', '[''south'', ''separation'', ''disunion'', ''nonunion'', ''unnorth'']', 'the direction in which a compass needle normally points.', 'phía bắc', 'The wind is blowing from the north.', '{IELTS}', 'A1', 'Geography'),
  ('sensible', '/ˈsensəbl/', '[''practical'', ''reasonable'', ''sensitive'', ''tenable'', ''well-founded'']', '[''foolish'', ''unreasonable'', ''insensible'', ''insensitive'', ''imperceptible'']', 'chosen in accordance with wisdom or prudence; practical.', 'hợp lý, khôn ngoan', 'It was a sensible decision to bring an umbrella.', '{IELTS}', 'B2', 'Adjectives'),
