  ('immigrant', '/ˈɪmɪgrənt/', '[''migrant'', ''immigrate'']', '[''emigrant'', ''migrant'']', 'a person who comes to live permanently in a foreign country', 'người nhập cư', 'The city has a large population of first-generation immigrants.', '{IELTS}', 'B1', 'People'),
  ('immigrate', '/ˈɪmɪgreɪt/', '[''move'', ''immigration'', ''immigrant'']', '[''emigrate'', ''migrate'']', 'come to live permanently in a foreign country', 'nhập cư', 'His family decided to immigrate to Canada.', '{IELTS}', 'B2', 'Verbs'),
