  ('dispense', '/dɪˈspens/', '[''distribute'', ''administer'', ''mete out'', ''deal'', ''parcel out'']', '[''gather'', ''pense'']', 'to distribute or provide, as in shares or portions', 'phân phát, cấp phát', 'The machine dispenses drinks and snacks.', '{IELTS}', 'B2', 'Verbs'),
