  ('flexible', '/ˈfleksəbl/', '[''adaptable'', ''flexile'', ''elastic'', ''pliable'', ''pliant'']', '[''rigid'', ''inflexible'', ''uncompromising'', ''antagonistic'', ''inelastic'']', 'capable of bending easily without breaking; able to adapt to change', 'linh hoạt', 'Our schedule is flexible this week.', '{IELTS}', 'B1', 'Adjectives'),
  ('forbid', '/fərˈbɪd/', '[''prohibit'', ''interdict'', ''proscribe'', ''veto'', ''disallow'']', '[''allow'', ''permit'', ''let'', ''unforbid'', ''disforbid'']', 'to refuse to allow something', 'cấm', 'Smoking is forbidden inside the building.', '{IELTS}', 'B1', 'Verbs'),
  ('forecast', '/ˈfɔːrkæst/', '[''prediction'', ''prognosis'', ''calculate'', ''estimate'', ''reckon'']', '[''ground'', ''unforecast'', ''disforecast'']', 'a prediction or estimate of future events, especially weather', 'dự báo', 'The weather forecast predicts rain tomorrow.', '{IELTS}', 'B1', 'Abstract'),
