insert into vocab_cards (word, phonetic, synonym, antonym, meaning_en, meaning_vi, example_sentence, exam_type, cefr_level, category) values
  ('benefit', '/ˈbenɪfɪt/', 'advantage', 'disadvantage', 'an advantage or helpful result.', 'lợi ích', 'Regular exercise has many health benefits.', '{TOEIC}', 'B1', 'Business'),
  ('an', '/ən/', 'a', NULL, 'The form of ''a'' used before vowel sounds; the indefinite article.', 'một (dùng trước nguyên âm)', 'He ate an apple for a snack.', '{IELTS}', 'A1', 'Grammar'),
  ('if', '/ɪf/', 'whether', NULL, 'A conjunction expressing a condition or supposition.', 'nếu', 'If it rains, we will stay indoors.', '{IELTS}', 'A1', 'Grammar'),
  ('am', '/æm/', NULL, NULL, 'First-person singular present tense of ''be''.', 'tôi là, tôi đang', 'I am happy to help.', '{IELTS}', 'A1', 'Grammar'),
  ('is', '/ɪz/', NULL, 'are', 'Third-person singular present tense of ''be''.', 'là, đang (ngôi thứ ba số ít)', 'She is a talented musician.', '{IELTS}', 'A1', 'Grammar'),
  ('shall', '/ʃæl/', 'will', NULL, 'Auxiliary used (especially in first person) for the future tense or strong intention.', 'sẽ (trang trọng)', 'Shall we begin the meeting?', '{IELTS}', 'A1', 'Grammar'),
  ('their', '/ðɛr/', NULL, NULL, 'Possessive determiner: belonging to or associated with people previously mentioned.', 'của họ', 'The students submitted their assignments on time.', '{IELTS}', 'A1', 'Grammar'),
  ('except', '/ɪkˈsɛpt/', 'excluding', 'including', 'Not including; other than; used to introduce an exception.', 'ngoại trừ', 'Everyone passed except Tom.', '{IELTS}', 'A2', 'Grammar'),
  ('to', '/tuː/', NULL, 'from', 'Preposition expressing direction or destination; also placed before a verb infinitive.', 'đến, để', 'I am going to the store.', '{IELTS}', 'A1', 'Grammar'),
  ('for', '/fɔːr/', NULL, 'against', 'Preposition indicating purpose, benefit, duration, or exchange.', 'cho, để, vì', 'This gift is for you.', '{IELTS}', 'A1', 'Grammar'),
  ('therefore', '/ˈðɛrˌfɔːr/', 'hence', NULL, 'For that reason; consequently; as a result.', 'do đó, vì vậy', 'He failed the exam; therefore, he must retake the course.', '{IELTS}', 'B1', 'Grammar'),
  ('above', '/əˈbʌv/', 'over', 'below', 'In a higher position than; greater in number or level.', 'ở trên, trên', 'The clock is hanging above the door.', '{IELTS}', 'A2', 'Grammar'),
  ('below', '/bɪˈloʊ/', 'under', 'above', 'In a lower position than; less than.', 'ở dưới, dưới', 'The temperature dropped below zero.', '{IELTS}', 'A2', 'Grammar'),
  ('neither', '/ˈniːðər/', 'nor', 'both', 'Not one nor the other of two; none of the two.', 'không cái nào (trong hai)', 'Neither option seems good.', '{IELTS}', 'A2', 'Grammar'),
  ('none', '/nʌn/', 'zero', 'some', 'Not any; no person or thing; zero amount.', 'không ai, không cái gì', 'None of the answers were correct.', '{IELTS}', 'A2', 'Grammar'),
